#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
apply_changes.py  —  یک فایل، همه چیز توش هست. (نسخه اصلاح‌شده - اعمال هوشمندتر)

طرز استفاده (فقط همین):
  1) این فایل رو تو یه فولدر بذار.
  2) فایل نسخه جدید اسکریپت (.js) رو هم همون تو فولدر بذار.
  3) با پایتون اجرا کن:

       python3 apply_changes.py

خروجی به اسم output.js تو همون فولدر ساخته میشه؛ همون نسخه جدید به‌علاوه‌ی
تغییرات همیشگی (پنل ادمین، لایسنس، تاریخ شمسی روی کانفیگ‌ها، تغییر نام
اپراتورها به انگلیسی و بقیه‌ی موارد).

--------------------------------------------------------------------------
تغییری که نسبت به نسخه قبلی این فایل داده شده:
قبلاً هر تیکه (hunk) فقط وقتی اعمال می‌شد که *کل* متن اطرافش (چند خط قبل و
بعد) دقیقاً عین چیزی باشه که موقع ساخت پچ ثبت شده. اگر نویسنده‌ی اصلی اسکریپت
همون‌جاها (حتی چند کاراکتر، مثل اضافه‌شدن یه پارامتر جدید به تابع یا یه
متغیر با اسم دیگه) رو توی نسخه‌ی جدیدش عوض کرده بود، کل تیکه رد می‌شد و
اصلاً اعمال نمی‌شد - حتی اگه محل درج تغییر کاملاً مشخص بود.

الان اگه تطبیق کامل جواب نده، اسکریپت به‌ترتیب از دو طرفِ متنِ اطراف (ابتدا
و انتها) کم می‌کنه و دوباره امتحان می‌کنه، تا جایی که یه محل یکتا و مطمئن
برای درج/جایگزینی پیدا بشه؛ بدون این‌که به خطوطی که مستقل از این تغییرات
در نسخه‌ی جدید عوض شدن دست بزنه (اونا دست‌نخورده باقی می‌مونن). هر جا از این
حالتِ منعطف استفاده بشه، یه خط هشدار توی خروجی چاپ می‌شه که بدونی کجا دقیق
صد در صد نبوده.
"""

import base64
import glob
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
OUTPUT_NAME = "output.js"
REJECT_NAME = "output_not_applied.txt"

# ---------------------------------------------------------------------------
# تغییرات ذخیره شده (به صورت base64 تا هیچ مشکلی تو کاراکترها پیش نیاد)
# ---------------------------------------------------------------------------
PATCH_B64 = """"""


def get_patch_text():
    return base64.b64decode(PATCH_B64).decode("utf-8")


def parse_hunks(patch_text):
    """یونیفاید-دیف رو به لیستی از تیکه‌ها (hunk) تبدیل می‌کنه."""
    lines = patch_text.splitlines()
    hunks = []
    i = 0
    while i < len(lines) and not lines[i].startswith("@@"):
        i += 1
    while i < len(lines):
        if not lines[i].startswith("@@"):
            i += 1
            continue
        i += 1
        old_block = []
        new_block = []
        while i < len(lines) and not lines[i].startswith("@@") and not lines[i].startswith("--- ") and not (lines[i].startswith("+++ ")):
            line = lines[i]
            if line.startswith("\\"):
                i += 1
                continue
            if line == "":
                old_block.append("")
                new_block.append("")
            elif line[0] == " ":
                old_block.append(line[1:])
                new_block.append(line[1:])
            elif line[0] == "-":
                old_block.append(line[1:])
            elif line[0] == "+":
                new_block.append(line[1:])
            else:
                old_block.append(line)
                new_block.append(line)
            i += 1
        hunks.append((old_block, new_block))
    return hunks


def _common_prefix_len(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[i] == b[i]:
        i += 1
    return i


def _common_suffix_len(a, b, avoid):
    """avoid: چند خط از ابتدا نادیده گرفته بشه تا با پیشوند قاطی نشه."""
    n = min(len(a), len(b)) - avoid
    i = 0
    while i < n and a[len(a) - 1 - i] == b[len(b) - 1 - i]:
        i += 1
    return i


def _find_all(lines, block):
    n, m = len(lines), len(block)
    if m == 0:
        return []
    return [start for start in range(0, n - m + 1) if lines[start:start + m] == block]


def find_block(lines, block, hint_pos):
    """دنبال دنباله‌ی block تو lines می‌گرده و نزدیک‌ترین موقعیت به hint_pos رو برمی‌گردونه."""
    if len(block) == 0:
        return hint_pos
    matches = _find_all(lines, block)
    if not matches:
        return None
    return min(matches, key=lambda p: abs(p - hint_pos))


def apply_patch(source_text, patch_text, warn=None):
    """
    تیکه‌ها رو روی متن مبدا اعمال می‌کنه.
    اول تلاش می‌کنه با تطبیق کامل (مثل قبل). اگه جواب نداد، به‌ترتیب از
    ابتدا و/یا انتهای متن اطرافِ تغییر کم می‌کنه (فقط تا جایی که آن خطوط
    خودشون واقعاً بخشی از متن ثابت/بدون‌تغییر پچ باشن، نه بخشی از خودِ
    تغییر) تا یه محل یکتا برای اعمال تغییر پیدا کنه. خطوطی که این‌طوری کنار
    گذاشته می‌شن دست‌نخورده از فایل مقصد باقی می‌مونن.
    """
    hunks = parse_hunks(patch_text)
    lines = source_text.split("\n")
    failed = []
    approx_pos = 0

    for idx, (old_block, new_block) in enumerate(hunks, start=1):
        p_max = _common_prefix_len(old_block, new_block)
        s_max = _common_suffix_len(old_block, new_block, p_max)

        best = None
        for total in range(0, p_max + s_max + 1):
            match = None
            for h in range(0, min(total, p_max) + 1):
                t = total - h
                if t > s_max:
                    continue
                sub_old = old_block[h:len(old_block) - t] if t > 0 else old_block[h:]
                pos = find_block(lines, sub_old, approx_pos)
                if pos is not None:
                    match = (h, t, pos, sub_old)
                    break
            if match:
                best = match
                break

        if best is None:
            failed.append((idx, old_block))
            continue

        h, t, pos, sub_old = best
        sub_new = new_block[h:len(new_block) - t] if t > 0 else new_block[h:]
        lines = lines[:pos] + sub_new + lines[pos + len(sub_old):]
        approx_pos = pos + len(sub_new)

        if (h or t) and warn:
            warn(idx, h, t)

    return "\n".join(lines), failed


def find_input_file():
    candidates = []
    for path in glob.glob(os.path.join(SCRIPT_DIR, "*.js")):
        name = os.path.basename(path)
        if name == OUTPUT_NAME:
            continue
        candidates.append(path)

    if not candidates:
        print("خطا: هیچ فایل .js ای تو این فولدر پیدا نشد.")
        print("فایل نسخه جدید اسکریپت رو کنار همین فایل پایتون بذار و دوباره اجرا کن.")
        sys.exit(1)

    if len(candidates) > 1:
        print("بیشتر از یک فایل .js تو این فولدر پیدا شد:")
        for c in candidates:
            print("  -", os.path.basename(c))
        print("لطفاً فقط یک فایل (همون نسخه‌ی جدید) رو تو فولدر نگه دار.")
        sys.exit(1)

    return candidates[0]


def main():
    new_file = find_input_file()
    print("فایل پیدا شده:", os.path.basename(new_file))

    with open(new_file, "r", encoding="utf-8") as f:
        source_text = f.read()

    patch_text = get_patch_text()

    warnings = []

    def warn(idx, h, t):
        msg = "  - تیکه %d: با %d خط کمتر از ابتدا و %d خط کمتر از انتهای متن اطراف (چون اون بخش تو نسخه جدید یه‌کم فرق داشت، ولی خودِ محل درج پیدا و اعمال شد)" % (idx, h, t)
        warnings.append(msg)

    result_text, failed = apply_patch(source_text, patch_text, warn=warn)
    if not result_text.endswith("\n"):
        result_text += "\n"

    output_path = os.path.join(SCRIPT_DIR, OUTPUT_NAME)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(result_text)

    reject_path = os.path.join(SCRIPT_DIR, REJECT_NAME)
    if failed:
        with open(reject_path, "w", encoding="utf-8") as f:
            for idx, block in failed:
                f.write("=== تیکه شماره %d پیدا نشد و اعمال نشد ===\n" % idx)
                f.write("\n".join(block))
                f.write("\n\n")
        print("توجه: %d تا از تغییرات به‌صورت خودکار جا نیفتاد." % len(failed))
        print("جزئیاتش اینجاست:", reject_path)
        print("(احتمالاً نسخه جدید خیلی با نسخه قبلی فرق داره - این بخش رو باید دستی اضافه کنی)")
    else:
        if os.path.exists(reject_path):
            os.remove(reject_path)
        print("همه تغییرات با موفقیت اعمال شد.")

    if warnings:
        print()
        print("نکته: بعضی تیکه‌ها با کمی انعطاف اعمال شدن (پیشنهاد می‌شه output.js رو دور همون قسمت‌ها یه نگاه بندازی):")
        for w in warnings:
            print(w)

    print()
    print("خروجی ساخته شد:", output_path)


if __name__ == "__main__":
    main()
